// Parse and validate input
// Phase 2: EN-pivot with structured output generation
const input = $input.first().json;
const body = input.body || input;

const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen',
  'de': 'allemand',
  'it': 'italien'
};

if (!body.text) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TEXT', message: 'text is required' }
    }
  }];
}


// ── Fournisseur de la TRADUCTION (azy.daily#642, décision de Franck du 2026-11-14) ──
// Jusqu'ici les trois appels tapaient api.anthropic.com en dur : `model` était
// pilotable, mais seulement dans le catalogue Anthropic. Ils passent désormais par
// /webhook/llm-call-messages, le relais multi-fournisseurs déjà en service — donc
// anthropic | openai | google, avec le MÊME corps de requête (`messages[]`).
//
// ⚠️ La valeur Gemini est `google`, PAS `gemini` : c'est l'énumération de
// llm-call-messages, et une valeur hors liste y part en 400. On la vérifie ICI
// pour rendre une erreur qui nomme le champ fautif, plutôt qu'un 400 du relais
// que l'appelant ne saurait pas rattacher à `provider`.
const FOURNISSEURS = ['anthropic', 'openai', 'google', 'mistral', 'ollama-cloud'];
const provider = String(body.provider || 'anthropic').toLowerCase();

// BYOT, même cascade que la vérification — surtout pas une clé d'environnement.
// `api_key` reste la clé Anthropic historique : un appelant qui n'envoie pas
// `provider` ne change rien à ce qu'il faisait hier.
const providerCle = body.provider_api_key
  || (provider === 'anthropic' ? body.api_key : null)
  || body.plugin_context?.api_keys?.[provider]
  || null;

if (FOURNISSEURS.indexOf(provider) === -1) {
  return [{
    json: {
      success: false,
      error: { code: 'INVALID_PROVIDER',
        message: 'provider must be one of ' + FOURNISSEURS.join(', ') + ' and Gemini is named google' }
    }
  }];
}

// ⚠️ Ce n'est plus « api_key est requis » mais « une clé pour le fournisseur
// demandé est requise ». Assouplissement pur — provider absent vaut anthropic,
// donc api_key seul suffit encore, exactement comme avant.
// Pas de deux-points dans le message : n8n ne garde que ce qui suit le dernier.
if (!providerCle) {
  return [{
    json: {
      success: false,
      error: {
        code: provider === 'anthropic' ? 'MISSING_API_KEY' : 'MISSING_PROVIDER_API_KEY',
        message: provider === 'anthropic'
          ? 'api_key is required'
          : 'aucune cle pour le fournisseur ' + provider
            + ' — fournir provider_api_key ou plugin_context.api_keys.' + provider
      }
    }
  }];
}

const sourceLanguage = body.source_language || 'he';
const targetLanguage = body.target_language || 'fr';
const referenceTranslation = body.reference_translation || null;
const hasReferenceTranslation = !!referenceTranslation;

// Phase 2: Determine translation strategy
// - hasReferenceTranslation=true → use existing EN as pivot (Phase 1)
// - hasReferenceTranslation=false AND target!='en' → generate EN+target structured
// - target='en' → direct HE→EN translation
const needsStructuredGeneration = !hasReferenceTranslation && targetLanguage !== 'en' && sourceLanguage !== 'en';
const isDirectToEnglish = targetLanguage === 'en';

// ── Vérification de traduction (azy.daily#541, décision du 2026-10-18) ──
// La vérification ANNOTE, elle ne substitue jamais. Un modèle relit la
// traduction et rend un avis ; le texte livré reste celui du traducteur.
//
// ⚠️ Pourquoi aucune substitution automatique : une divergence peut être
// minuscule en caractères et décisive en sens (le sens d'un mot, une
// nuance). Aucun seuil calculable ici — longueur, similarité — ne mesure
// le sens. Trancher reviendrait à confier le texte final à un modèle dont
// nous ne vérifions rien. On rend donc les deux versions visibles.
//
// BYOT : la vérification n'a lieu que si une clé est disponible pour son
// fournisseur. Si verify_provider vaut le fournisseur de la traduction
// (anthropic), on réutilise api_key — aucune seconde clé à fournir.
const verifyDemandee = body.verify !== false;

// ── RELECTEUR INDÉPENDANT QUAND C'EST POSSIBLE (azy.daily#669, point 5) ─────
//
// Le défaut valait `anthropic` — exactement le fournisseur de la traduction —
// et `verifyCle` retombait sur `body.api_key`. Le modèle se relisait donc
// LUI-MÊME : `claude-sonnet-4-6` des deux côtés. Il repère les fautes de forme,
// beaucoup moins les contresens qu'il vient de produire.
//
// ⚠️ ON NE PEUT PAS SIMPLEMENT CHANGER LE DÉFAUT.
// `verifyActive = verifyDemandee && !!verifyCle` : viser un fournisseur dont
// l'appelant n'a pas la clé DÉSACTIVERAIT la relecture, en silence et sans
// changement de code HTTP, pour tous ceux qui n'envoient que `api_key`. Le
// remède serait pire que le défaut.
//
// ⚠️ ET ON N'INVENTE JAMAIS UN NOM DE MODÈLE.
// `LLM - Call Messages` EXIGE `model` et n'a aucun défaut par fournisseur
// (« model requis (ex: claude-haiku-4-5-20251001, gpt-4o) »). Choisir un
// fournisseur sans modèle reviendrait à en fabriquer un — or un modèle faux est
// pire qu'un modèle absent (azy.daily#201), et le `claude-sonnet-4` mort de
// n8n-workflows#462 a déjà coûté un 404 latent.
//
// D'où la règle : un autre fournisseur n'est retenu AUTOMATIQUEMENT que si
// l'appelant a fourni À LA FOIS sa clé (`plugin_context.api_keys[p]`) ET son
// modèle (`verify_models[p]`). Sinon on garde le comportement actuel — la
// relecture a lieu, mais elle n'est pas indépendante — et on le DIT, au lieu de
// le taire : `verify_independant` et son motif sortent dans la réponse.
const trousseau = (body.plugin_context && body.plugin_context.api_keys) || {};
const modelesTiers = body.verify_models || {};
// Ordre stable et documenté. Le traducteur est retiré, donc pour une traduction
// anthropic le premier candidat est openai, puis google.
const ORDRE_RELECTEURS = ['anthropic', 'openai', 'google', 'mistral', 'ollama-cloud'];

let verifyProvider = body.verify_provider
  ? String(body.verify_provider).toLowerCase() : null;
let verifyModel = body.verify_model || null;
let independanceMotif;

if (verifyProvider) {
  // Choix explicite de l'appelant : on ne le discute pas.
  independanceMotif = 'demande_par_appelant';
} else {
  const candidat = ORDRE_RELECTEURS.find(
    (pr) => pr !== provider && trousseau[pr] && modelesTiers[pr]);
  if (candidat) {
    verifyProvider = candidat;
    verifyModel = modelesTiers[candidat];
    independanceMotif = 'choisi_dans_le_trousseau';
  } else {
    verifyProvider = 'anthropic';
    // Pourquoi l'indépendance a échoué — la distinction importe à l'appelant :
    // fournir un modèle est à sa portée, fournir une clé qu'il n'a pas, non.
    const aUneCleTierce = Object.keys(trousseau).some(
      (pr) => pr !== provider && trousseau[pr]);
    independanceMotif = aUneCleTierce
      ? 'aucun_modele_pour_un_autre_fournisseur'
      : 'aucune_cle_pour_un_autre_fournisseur';
  }
}
if (!verifyModel) verifyModel = 'claude-sonnet-4-6';

// ⚠️ FUITE DE CLÉ CORRIGÉE ICI — défaut introduit par n8n-workflows#579.
// L'écriture précédente était `(verifyProvider === 'anthropic' ? body.api_key
// : null)`. Elle supposait que `body.api_key` EST la clé Anthropic, ce qui
// était vrai tant que la traduction ne passait que par Anthropic. Depuis #579,
// `api_key` est la clé du fournisseur de TRADUCTION, quel qu'il soit : une
// traduction Gemini envoie une clé `AIza…`, et le repli l'aurait transmise à
// `api.anthropic.com`. Une clé part alors chez un fournisseur qui n'est pas le
// sien — exactement ce que la cascade de traduction interdit par ailleurs.
//
// La règle juste : on réutilise la clé de traduction UNIQUEMENT quand le
// relecteur est le MÊME fournisseur que le traducteur. Et on réutilise
// `providerCle`, la clé déjà résolue, plutôt que le champ brut.
const verifyCle = body.verify_api_key
  || (verifyProvider === provider ? providerCle : null)
  || trousseau[verifyProvider]
  || null;
const verifyActive = verifyDemandee && !!verifyCle;
// Indépendant = le relecteur n'est pas le fournisseur qui a traduit. Rendu même
// quand la relecture est sautée : savoir qu'elle AURAIT été non indépendante
// vaut mieux que de l'ignorer.
const verifyIndependant = verifyProvider !== provider;

return [{
  json: {
    jobId: body.job_id,
    segmentId: body.segment_id || null,
    text: body.text,
    referenceTranslation: referenceTranslation,
    hasReferenceTranslation: hasReferenceTranslation,
    needsStructuredGeneration: needsStructuredGeneration,
    isDirectToEnglish: isDirectToEnglish,
    sourceLanguage: sourceLanguage,
    sourceLangName: languageNames[sourceLanguage] || sourceLanguage,
    targetLanguage: targetLanguage,
    targetLangName: languageNames[targetLanguage] || targetLanguage,
    apiKey: body.api_key,
    provider: provider,
    providerCle: providerCle,
    model: body.model || 'claude-sonnet-4-6',
    context: body.context || {},
    metadata: body.metadata || {},
    verifyActive: verifyActive,
    verifyProvider: verifyProvider,
    verifyIndependant: verifyIndependant,
    verifyIndependanceMotif: independanceMotif,
    verifyModel: verifyModel,
    verifyCle: verifyCle,
    verifySautee: verifyDemandee && !verifyCle ? 'aucune_cle_pour_' + verifyProvider : (verifyDemandee ? null : 'desactivee_par_appelant')
  }
}];

// Phase 2: Extract structured EN+target translation from single LLM call
const input = $input.first().json;
const prevData = $('Parse Input').first().json;

try {
  // ── Enveloppe de llm-call-messages (azy.daily#642) ─────────────────────────
  // { success, data{ text, model, finish_reason }, meta{ provider, model, usage },
  //   metadata, _trace }  ·  en échec : { success:false, error{ code, message, http_status } }
  //
  // ⚠️ Le texte est en `data.text`. L'ancienne lecture `body.content[0].text`
  // était celle de la réponse BRUTE d'Anthropic, que le relais ne rend plus —
  // et elle aurait rendu VIDE en silence, sans erreur, pour tout fournisseur.
  const env = input.body !== undefined ? input.body : input;
  const httpCode = input.statusCode || 200;
  const meta = env.meta || {};
  const providerUtilise = meta.provider || null;
  const modelUtilise = meta.model || null;

  if (httpCode >= 400 || env.success === false) {
    const err = env.error || {};
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: {
          code: err.code || 'LLM_RELAY_ERROR',
          message: (err.message || 'erreur du relais LLM')
                 + ' [http ' + (err.http_status || httpCode) + ']'
        },
        ...prevData
      }
    }];
  }

  const content = (env.data && env.data.text) || '';
  const usage = meta.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: { code: 'EMPTY_RESPONSE', message: 'le fournisseur a rendu une reponse vide' },
        ...prevData
      }
    }];
  }

  // Parse JSON from response (handle potential markdown code blocks)
  let parsed;
  try {
    let jsonStr = content.trim();
    // Remove markdown code block if present
    if (jsonStr.startsWith('```')) {
      jsonStr = jsonStr.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
    }
    parsed = JSON.parse(jsonStr);
  } catch (parseErr) {
    // JSON parse failed - fallback to direct translation
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: { code: 'JSON_PARSE_ERROR', message: 'Failed to parse structured response: ' + parseErr.message },
        ...prevData
      }
    }];
  }

  // Validate required fields
  if (!parsed.english_pivot || !parsed.translation) {
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: { code: 'INVALID_STRUCTURE', message: 'Missing english_pivot or translation in response' },
        ...prevData
      }
    }];
  }

  // Success: return both translations
  return [{
    json: {
      success: true,
      translation: parsed.translation,
      english_pivot: parsed.english_pivot,
      method: 'structured_generation',
      generated_english: true,
      segment_id: prevData.segmentId,
      target_language: prevData.targetLanguage,
      tokens: {
        input_tokens: usage.prompt_tokens || 0,
        output_tokens: usage.completion_tokens || 0
      },
      // Provenance RÉELLE, telle que le relais la rend — et non le modèle demandé.
      // C'est elle que le Router enregistre désormais en base.
      provider_utilise: providerUtilise,
      model_utilise: modelUtilise
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      fallbackToDirectTranslation: true,
      error: { code: 'PARSE_ERROR', message: e.message },
      ...prevData
    }
  }];
}

// Phase 2: Extract fallback direct translation (HE→target without EN pivot)
const input = $input.first().json;
const prevData = $('Extract Structured').first().json;

try {
  // ── Enveloppe de llm-call-messages (azy.daily#642) ─────────────────────────
  // { success, data{ text, model, finish_reason }, meta{ provider, model, usage },
  //   metadata, _trace }  ·  en échec : { success:false, error{ code, message, http_status } }
  //
  // ⚠️ Le texte est en `data.text`. L'ancienne lecture `body.content[0].text`
  // était celle de la réponse BRUTE d'Anthropic, que le relais ne rend plus —
  // et elle aurait rendu VIDE en silence, sans erreur, pour tout fournisseur.
  const env = input.body !== undefined ? input.body : input;
  const httpCode = input.statusCode || 200;
  const meta = env.meta || {};
  const providerUtilise = meta.provider || null;
  const modelUtilise = meta.model || null;

  if (httpCode >= 400 || env.success === false) {
    const err = env.error || {};
    return [{
      json: {
        success: false,
        error: {
          code: err.code || 'LLM_RELAY_ERROR',
          message: (err.message || 'erreur du relais LLM')
                 + ' [http ' + (err.http_status || httpCode) + ']'
        }
      }
    }];
  }

  const content = (env.data && env.data.text) || '';
  const usage = meta.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        error: { code: 'EMPTY_RESPONSE', message: 'le fournisseur a rendu une reponse vide sur le repli' }
      }
    }];
  }

  // Log the original error that caused fallback
  const originalError = prevData.error || null;

  return [{
    json: {
      success: true,
      translation: content,
      english_pivot: null,
      method: 'direct_fallback',
      generated_english: false,
      fallback_reason: originalError ? originalError.code : 'unknown',
      tokens: {
        input_tokens: usage.prompt_tokens || 0,
        output_tokens: usage.completion_tokens || 0
      },
      // Provenance RÉELLE, telle que le relais la rend — et non le modèle demandé.
      // C'est elle que le Router enregistre désormais en base.
      provider_utilise: providerUtilise,
      model_utilise: modelUtilise
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: { code: 'PARSE_ERROR', message: e.message }
    }
  }];
}

// Extract direct translation
// RFC bilingual-translations-en-pivot: track EN pivot usage
const input = $input.first().json;
const prevData = $('Parse Input').first().json;

try {
  // ── Enveloppe de llm-call-messages (azy.daily#642) ─────────────────────────
  // { success, data{ text, model, finish_reason }, meta{ provider, model, usage },
  //   metadata, _trace }  ·  en échec : { success:false, error{ code, message, http_status } }
  //
  // ⚠️ Le texte est en `data.text`. L'ancienne lecture `body.content[0].text`
  // était celle de la réponse BRUTE d'Anthropic, que le relais ne rend plus —
  // et elle aurait rendu VIDE en silence, sans erreur, pour tout fournisseur.
  const env = input.body !== undefined ? input.body : input;
  const httpCode = input.statusCode || 200;
  const meta = env.meta || {};
  const providerUtilise = meta.provider || null;
  const modelUtilise = meta.model || null;

  if (httpCode >= 400 || env.success === false) {
    const err = env.error || {};
    return [{
      json: {
        success: false,
        error: {
          code: err.code || 'LLM_RELAY_ERROR',
          message: (err.message || 'erreur du relais LLM')
                 + ' [http ' + (err.http_status || httpCode) + ']'
        }
      }
    }];
  }

  const content = (env.data && env.data.text) || '';
  const usage = meta.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        error: { code: 'EMPTY_RESPONSE', message: 'le fournisseur a rendu une reponse vide' }
      }
    }];
  }

  // RFC: indicate if EN pivot was used
  const usedEnPivot = prevData.hasReferenceTranslation === true;

  return [{
    json: {
      success: true,
      translation: content,
      method: usedEnPivot ? 'en_pivot' : 'direct',
      used_en_reference: usedEnPivot,
      tokens: {
        input_tokens: usage.prompt_tokens || 0,
        output_tokens: usage.completion_tokens || 0
      },
      // Provenance RÉELLE, telle que le relais la rend — et non le modèle demandé.
      // C'est elle que le Router enregistre désormais en base.
      provider_utilise: providerUtilise,
      model_utilise: modelUtilise
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: { code: 'PARSE_ERROR', message: e.message }
    }
  }];
}

// ── Préparer la vérification de traduction (azy.daily#541) ──────────────────
// Converge les trois sorties (structured, fallback, direct) vers une relecture
// par un second modèle, chez n'importe quel fournisseur via llm-call-messages.
//
// ⚠️ CETTE ÉTAPE N'ÉCRASE RIEN. Elle demande un avis et le joint au résultat.
// La traduction livrée reste celle du traducteur. Raison : une divergence peut
// être minuscule en caractères et décisive en sens — le sens d'un mot, une
// nuance de registre. Aucun seuil calculable ici ne mesure le sens, donc nous
// ne laissons pas un workflow arbitrer. Les deux versions sortent côte à côte.
const resultat = $input.first().json;
const pd = $('Parse Input').first().json;

// Une traduction en échec ne se vérifie pas.
if (resultat.success !== true || !resultat.translation) {
  return [{ json: Object.assign({}, resultat, { verifyActive: false, verification: null,
    verify_skipped: 'traduction_absente',
    verify_independant: pd.verifyIndependant,
    verify_independance_motif: pd.verifyIndependanceMotif }) }];
}
if (!pd.verifyActive) {
  return [{ json: Object.assign({}, resultat, { verifyActive: false, verification: null,
    verify_skipped: pd.verifySautee || 'desactivee',
    verify_independant: pd.verifyIndependant,
    verify_independance_motif: pd.verifyIndependanceMotif }) }];
}

// L'invite demande explicitement de signaler les écarts de SENS, y compris
// ceux qui ne changent presque rien au texte — c'est le cas que nous voulons
// voir, et celui qu'un contrôle automatique ne saurait pas détecter.
const instruction = [
  'Tu relis une traduction de texte talmudique. Tu ne la remplaces pas.',
  '',
  'Signale en priorite les ecarts de SENS, meme minuscules en nombre de mots',
  "(sens d'un terme, nuance, registre, negation, portee d'une proposition).",
  'Un ecart court peut etre le plus grave. Ne te limite pas aux fautes visibles.',
  '',
  'Reponds UNIQUEMENT par un objet JSON, sans texte autour et sans balises de code :',
  '{ "approved": true|false, "confidence": 0.0-1.0,',
  '  "issues": [{ "severite": "sens"|"style"|"forme", "extrait": "...", "explication": "..." }],',
  '  "approved": true ou false — OBLIGATOIRE, jamais omis,',
  '  "suggestion": "ta propre traduction si tu en proposes une, meme si tu approuves",',
  '  "notes": "..." }'
].join('\n');

const corps = [
  'Original (' + pd.sourceLangName + ') :',
  pd.text,
  '',
  resultat.english_pivot ? 'Pivot anglais :\n' + resultat.english_pivot + '\n' : '',
  'Traduction a relire (' + pd.targetLangName + ') :',
  resultat.translation
].filter(Boolean).join('\n');

return [{ json: Object.assign({}, resultat, {
  verifyActive: true,
  verify_skipped: null,
  // ⚠️ HORS de `verification` : cet objet est STRICTEMENT la forme `review` de
  // torah.api, qui refuse les champs inconnus (422, et sur /save-batch c'est
  // tout le lot qui tombe). Un champ de confort va à côté, jamais dedans.
  verify_independant: pd.verifyIndependant,
  verify_independance_motif: pd.verifyIndependanceMotif,
  // Horodatage de l'APPEL au relecteur, pas de la sauvegarde — c'est ce que
  // `review.reviewed_at` attend côté torah.api (`created_at` porte déjà la
  // date d'écriture). Posé AVANT l'appel, donc exact ; le lire après la
  // réponse daterait la réception, pas la demande.
  // ⚠️ Hors de `_verify` : ce qui est dans `_verify` part dans le corps HTTP
  //    du relais, et nous n'ajoutons pas de champ inconnu à son contrat.
  _verify_demande_a: new Date().toISOString(),
  _verify: {
    provider: pd.verifyProvider,
    model: pd.verifyModel,
    api_key: pd.verifyCle,
    max_tokens: 2000,
    temperature: 0,
    system: instruction,
    messages: [{ role: 'user', content: corps }]
  }
}) }];

// ── Appliquer la vérification — ANNOTE, ne substitue jamais ─────────────────
// Trois états possibles, et aucun ne modifie `translation` :
//   verification = null   → non demandée, pas de clé, ou relecture indisponible
//   approved true         → le relecteur est d'accord
//   approved false        → DÉSACCORD CONSERVÉ : `verification.suggestion` porte
//                           sa proposition, `issues` les écarts relevés.
// L'appelant décide. C'est volontairement non résolu ici : un écart de sens
// peut tenir à un mot, et aucun calcul local ne distingue une correction
// décisive d'une réécriture abusive.
const entree = $input.first().json;
const prec = $('Préparer Vérification').first().json;
const base = Object.assign({}, prec);
delete base._verify;
delete base._verify_demande_a;

const brut = entree.body !== undefined ? entree.body : entree;
const code = entree.statusCode || 200;

const vide = (raison) => [{ json: Object.assign({}, base, {
  verification: null, verify_skipped: raison }) }];

if (code >= 400) return vide('relecteur_http_' + code);

// Le texte rendu par llm-call-messages, quel que soit le fournisseur.
//
// ⚠️ CORRECTIF (azy.daily#642) — il est en `data.text`, et nulle part ailleurs.
// Cette ligne lisait `content || text || message`, TROIS clés qui n'existent pas
// au premier niveau de l'enveloppe. La vérification retombait donc
// systématiquement sur `relecteur_reponse_vide` : jamais aucun avis, et aucune
// erreur pour le signaler — le chemin d'échec rend la traduction telle quelle.
// Les anciens noms sont conservés en repli au cas où un relais tiers les rende.
const texte = brut && (
  (brut.data && brut.data.text) || brut.content || brut.text || brut.message || ''
);
if (!texte || typeof texte !== 'string') return vide('relecteur_reponse_vide');

// Analyse tolérante : aucun fournisseur ne garantit du JSON nu. On retire les
// balises de code, puis on isole le premier objet. Un échec d'analyse n'est pas
// une erreur de traduction — on rend la traduction sans avis.
let avis = null;
try {
  let s = texte.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const d = s.indexOf('{'), fin = s.lastIndexOf('}');
  if (d >= 0 && fin > d) s = s.slice(d, fin + 1);
  avis = JSON.parse(s);
} catch (e) {
  return vide('relecteur_json_illisible');
}
if (!avis || typeof avis !== 'object') return vide('relecteur_json_illisible');

// ⚠️ `approved` DOIT être STRICTEMENT booléen — on ne l'invente jamais.
//
// L'écriture précédente, `avis.approved !== false`, traitait un verdict MUET
// (clé absente, `null`, type inattendu) comme une APPROBATION : le relecteur
// n'avait rien dit, et nous enregistrions son accord. Trois exemplaires du même
// biais ont été trouvés le 2026-11-15 (azy.daily#669) — `status: 'approved'`
// écrit en dur dans le Router, le défaut Pydantic côté torah.api, et cette
// ligne. Tous trois disaient « en cas de doute, approuver ». Dans une chaîne de
// validation, le défaut sûr est l'inverse : pas de verdict.
//
// ⚠️ ET AUCUN CONTRÔLE CÔTÉ API NE PEUT RATTRAPER CE CAS. torah.api impose
// désormais `review.approved` obligatoire et `StrictBool`, mais sa validation ne
// voit que la valeur reçue : un `true` fabriqué ici lui arrive impeccable. Le
// seul endroit où l'information « le relecteur n'a pas tranché » existe encore,
// c'est ici. La perdre est irréversible.
//
// La forme `x !== false` est la plus trompeuse des trois : elle ressemble à une
// précaution contre un `false` manquant, alors qu'elle convertit `undefined`,
// `null` et toute valeur inattendue en approbation.
if (avis.approved !== true && avis.approved !== false) {
  return vide('relecteur_avis_sans_verdict');
}
const approuve = avis.approved;
// ── Normalisation avant envoi : un 422 d'api ferait perdre LA TRADUCTION ────
// torah.api valide strictement `review` (azy.daily#669) : `severite` ∈
// {sens, style, forme}, `confidence` ∈ [0,1], `extrait`/`explication` chaînes.
// Nous transmettions la sortie BRUTE du relecteur. Un modèle rendant
// `severite: "grammar"` ou `confidence: 95` (en pourcents) provoquerait un 422
// sur tout l'enregistrement — verdict ET traduction. Disproportionné : on
// normalise ici, et l'API reste stricte en dernier rempart.
const c = avis.confidence;
const confiance = (typeof c === 'number' && isFinite(c) && c >= 0 && c <= 1) ? c : null;

const SEVERITES = ['sens', 'style', 'forme'];
const problemes = [];
let ecartees = 0;
for (const pb of (Array.isArray(avis.issues) ? avis.issues : [])) {
  // Sans extrait ni explication, l'écart n'est pas exploitable : on l'écarte.
  if (!pb || typeof pb !== 'object' ||
      typeof pb.extrait !== 'string' || typeof pb.explication !== 'string') {
    ecartees++;
    continue;
  }
  // Une sévérité hors jeu est RAMENÉE à `forme`, la moins affirmative, plutôt
  // que de jeter l'écart : perdre une remarque est plus grave que la déclasser.
  const sev = String(pb.severite || '').toLowerCase();
  problemes.push({
    severite: SEVERITES.indexOf(sev) >= 0 ? sev : 'forme',
    extrait: pb.extrait,
    explication: pb.explication
  });
}

return [{ json: Object.assign({}, base, {
  // `translation` est intacte, et le reste ci-dessous ne fait que l'éclairer.
  verification: {
    // Forme arrêtée avec torah.api le 2026-11-15 (azy.daily#669) : relecteur
    // IMBRIQUÉ, pour que cet objet puisse partir tel quel dans `review`.
    reviewer: { provider: prec._verify.provider, model: prec._verify.model },
    reviewed_at: prec._verify_demande_a || new Date().toISOString(),
    approved: approuve,
    confidence: confiance,
    issues: problemes,
    // Nombre d'écarts retirés à la normalisation. Devrait toujours valoir 0 :
    // s'il ne vaut pas 0, c'est un signal sur le relecteur, pas sur le texte.
    issues_ecartees: ecartees,
    // ⚠️ PLUS CONDITIONNÉE À LA DÉCISION. Un relecteur peut approuver ET
    // proposer mieux — « c'est acceptable, mais voici mieux » est l'avis le
    // plus utile qu'il puisse rendre, et nous le jetions
    // (`suggestion: approuve ? null : …`). Elle est stockée et JAMAIS servie.
    suggestion: avis.suggestion || null,
    notes: avis.notes || null
    // ⚠️ `divergence` RETIRÉ. Il valait `!approuve` : le même fait écrit deux
    // fois, et un booléen dérivé stocké finit par diverger de ce qu'il résume.
    // Franck a tranché contre une colonne séparée, pour la même raison.
    // « Approuvé avec réserves » se calcule à la lecture :
    //     approved === true && (issues.length > 0 || suggestion !== null)
  },
  verify_skipped: null
}) }];
